def seed_fish(apps, schema_editor):
    Fish = apps.get_model("fish", "Fish")
    database = schema_editor.connection.alias
    items = []
    for entry in csv.DictReader(StringIO(FISH_TSV), delimiter="\t"):
        super_weight = int(entry["SuperTrophyWeight"])
        items.append(Fish(
            id=int(entry["ID"]),
            name=entry["Name"],
            trophy_weight=int(entry["TrophyWeight"]),
            super_trophy_weight=None if super_weight == 9999999 else super_weight,
            rarity=int(entry["Rarity"]),
        ))
    Fish.objects.using(database).bulk_create(items)


class Migration(migrations.Migration):
    dependencies = [("fish", "0001_initial")]

    operations = [
        migrations.RunPython(seed_fish, reverse_code=migrations.RunPython.noop),
    ]
